{
  "packet_id": "H6-T01-1",
  "claim_id": "C015",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C015.component",
    "value": "The provisional persistence rule should be adopted before inspecting the prospective sequence.",
    "scope": "Prospective investigation; this fixes the ordering of rule selection and sequence inspection.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P011 explicitly prescribes adopting the rule before inspecting the prospective sequence."
    }
  },
  "signal_basis": {
    "component_id": "C015.signal_basis",
    "value": "Evaluate daily observations and weekly summaries against a provisional rule requiring recurrence on multiple booking days in each investigation week and the same stage having the greatest documented delay burden in both weeks. Withhold a bottleneck determination if missing records could reverse the ranking or observations are too sparse.",
    "scope": "Two-week prospective investigation using a practical selection rule, without statistical proof or causal identification.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the observation schedule, persistence criterion, missingness and sparsity restrictions, and inferential limits."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C015.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This procedural claim does not require a conditional empirical warrant."
    }
  },
  "rationale": "Adopting the criterion before inspecting the sequence provides a fixed standard for evaluating recurrence and limits tailoring the criterion to observed patterns. This licenses the claimed procedural ordering within its narrow scope; it does not establish that the chosen threshold proves persistence or causation.",
  "uncertainty": "The rule's empirical adequacy remains limited by the short investigation and sparse observations, but that does not undermine the warranted ordering of rule selection and inspection.",
  "anomalies": []
}
